/**
 * @planks("I type {string} into the new-todo input")
 * @planks("I press Enter")
 * @planks("I click the toggle-all checkbox")
 * @planks("I complete the todo {string}")
 * @planks("I click the destroy button for {string}")
 * @planks("I start editing {string}")
 * @planks("I change the edit value to {string}")
 * @planks("I press Enter while editing")
 * @planks("I blur the edit input")
 * @planks("I press Escape while editing")
 * @planks('I click "Clear completed"')
 * @planks("the page is reloaded")
 * @planks("the route is {string}")
 * @planks("all todos are completed")
 * @planks("the todo list has a todo {string}")
 * @planks("the todo list has todos: {string}")
 * @planks("the todo list has todos: {string}, {string}")
 * @planks("the todo list has todos: {string}, {string}, {string}")
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todoApp = document.querySelector('.todoapp');
  var newTodo = document.querySelector('.new-todo');
  var toggleAll = document.getElementById('toggle-all');
  var todoList = document.querySelector('.todo-list');
  var footer = document.querySelector('.footer');
  var main = document.querySelector('.main');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelector('.filters');

  var todos = [];
  var nowShowing = 'all';

  function uuid() {
    var i, d = Date.now();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
      i = (d + Math.random() * 16) % 16 | 0;
      d = Math.floor(d / 16);
      return (c === 'x' ? i : (i & 0x3) | 0x8).toString(16);
    });
  }

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
    try {
      var storedRoute = localStorage.getItem(STORAGE_KEY + '-route');
      if (storedRoute) nowShowing = storedRoute;
    } catch (e) {}
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilteredTodos() {
    if (nowShowing === 'active') return todos.filter(function (t) { return !t.completed; });
    if (nowShowing === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function pluralize(count, word) {
    return count === 1 ? word : word + 's';
  }

  function todoId(el) {
    var li = el && el.closest ? el.closest('li') : null;
    return li ? li.dataset.id : null;
  }

  function findTodoIndex(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return i;
    }
    return -1;
  }

  function render() {
    var filtered = getFilteredTodos();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.className = 'completed';
      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      todoList.appendChild(li);
    });

    main.style.display = todos.length > 0 ? '' : 'none';
    footer.style.display = todos.length > 0 ? '' : 'none';

    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralize(activeCount, 'item') + ' left';

    clearCompleted.style.display = completedCount > 0 ? '' : 'none';
    clearCompleted.textContent = 'Clear completed';

    toggleAll.checked = activeCount === 0 && todos.length > 0;

    var filterLinks = filters.querySelectorAll('a');
    filterLinks.forEach(function (a) {
      var href = a.getAttribute('href');
      if (href === '#/' + (nowShowing === 'all' ? '' : nowShowing === 'active' ? 'active' : 'completed')) {
        a.className = 'selected';
      } else {
        a.className = '';
      }
    });

    if (nowShowing === 'all') {
      var allLink = filters.querySelector('a[href="#/"]');
      if (allLink) allLink.className = 'selected';
    }
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({ id: uuid(), title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    var idx = findTodoIndex(id);
    if (idx === -1) return;
    todos[idx].completed = !todos[idx].completed;
    saveTodos();
    render();
  }

  function destroyTodo(id) {
    var idx = findTodoIndex(id);
    if (idx === -1) return;
    todos.splice(idx, 1);
    saveTodos();
    render();
  }

  function toggleAllTodos(checked) {
    todos.forEach(function (t) { t.completed = checked; });
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function editTodo(id, title) {
    var idx = findTodoIndex(id);
    if (idx === -1) return;
    var trimmed = title.trim();
    if (trimmed) {
      todos[idx].title = trimmed;
      saveTodos();
      render();
    } else {
      destroyTodo(id);
    }
  }

  function cancelEdit(id) {
    render();
  }

  function setRoute(route) {
    nowShowing = route;
    render();
  }

  // --- Event handlers ---

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var id = todoId(e.target);
      if (id) toggleTodo(id);
    }
  });

  todoList.addEventListener('click', function (e) {
    if (e.target.classList.contains('destroy')) {
      var id = todoId(e.target);
      if (id) destroyTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest && e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    li.className = 'editing';
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
      editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
    }
  });

  todoList.addEventListener('keydown', function (e) {
    var editInput = e.target.closest && e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    var id = li.dataset.id;
    if (e.keyCode === ENTER_KEY) {
      editTodo(id, editInput.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      li.className = li.className.replace(/\bediting\b/g, '').trim();
      cancelEdit(id);
    }
  });

  todoList.addEventListener('blur', function (e) {
    var editInput = e.target.closest && e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (li.className.indexOf('editing') === -1) return;
    var id = li.dataset.id;
    editTodo(id, editInput.value);
  }, true);

  toggleAll.addEventListener('change', function (e) {
    toggleAllTodos(e.target.checked);
  });

  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // --- Routing ---

  window.addEventListener('hashchange', function () {
    var route = window.location.hash.replace('#/', '') || 'all';
    setRoute(route);
    try { localStorage.setItem(STORAGE_KEY + '-route', route); } catch (e) {}
  });

  // --- Init ---

  loadTodos();

  var initialRoute = window.location.hash.replace('#/', '') || 'all';
  // If no hash, use persisted filter
  if (!window.location.hash && nowShowing !== 'all') {
    initialRoute = nowShowing;
  }
  nowShowing = initialRoute;
  render();

  // Expose reload for verification
  window.__reloadTodos = function() {
    loadTodos();
    render();
  };
})();

